using System.Collections.Immutable;
using System.Text;
using Norse.Abstractions.Emit;

namespace Norse.Infrastructure.Web.Client.Generator;

static class ClientRegistrationEmitter
{
	internal static string Emit(string rootNamespace, ImmutableArray<string> contractTypeNames, ImmutableArray<string> payloads)
	{
		StringBuilder builder = new();
		builder.AppendCSharp(
			$$"""
			// <auto-generated/>
			namespace {{rootNamespace}};

			#pragma warning disable CS1591 // Generated registration: no XML doc comments.
			/// <summary>Generated by Norse.Infrastructure.Web.Client.Generator — compile-time gRPC client proxy registration decoded through OutcomeClientInterceptor.</summary>
			public static class NorseGrpcClientRegistration
			{
				/// <summary>Registers the Outcome&lt;T&gt; passthrough surrogates, idempotent per type and safe under concurrent first call.</summary>
				public static void RegisterNorseOutcomeSurrogates() =>
					global::Norse.Infrastructure.Web.Grpc.WireModelRegistrationGuard.EnsureRegistered(
						global::ProtoBuf.Meta.RuntimeTypeModel.Default,
						typeof(NorseGrpcClientRegistration),
						() =>
						{
							var model = global::ProtoBuf.Meta.RuntimeTypeModel.Default;
							global::Norse.Infrastructure.Web.Grpc.IdentifierSerializers.Register(model);
							global::Norse.Infrastructure.Web.Grpc.ResultSerializers.Register(model);
			{{SurrogateGuards(payloads)}}
						});

				/// <summary>
				/// Registers every discovered Norse contract's proxy over <paramref name="callInvoker"/>, decoded
				/// through OutcomeClientInterceptor — the host builds the invoker (base address, credentials,
				/// transport are host policy), this method does the rest.
				/// </summary>
				public static global::Microsoft.Extensions.DependencyInjection.IServiceCollection AddNorseGrpcClients(
					this global::Microsoft.Extensions.DependencyInjection.IServiceCollection services,
					global::Grpc.Core.CallInvoker callInvoker)
				{
					RegisterNorseOutcomeSurrogates();
					var invoker = global::Grpc.Core.Interceptors.CallInvokerExtensions.Intercept(
						callInvoker, new global::Norse.Infrastructure.Web.Client.Grpc.OutcomeClientInterceptor());
			{{AddClients(contractTypeNames)}}
					return services;
				}

				/// <summary>
				/// Convenience overload over a <see cref="global::Grpc.Net.Client.GrpcChannel"/> — delegates to
				/// the <see cref="global::Grpc.Core.CallInvoker"/> overload via the channel's own invoker.
				/// </summary>
				public static global::Microsoft.Extensions.DependencyInjection.IServiceCollection AddNorseGrpcClients(
					this global::Microsoft.Extensions.DependencyInjection.IServiceCollection services,
					global::Grpc.Net.Client.GrpcChannel channel) =>
					AddNorseGrpcClients(services, channel.CreateCallInvoker());
			}
			#pragma warning restore CS1591
			""");
		return builder.ToString();
	}

	static string SurrogateGuards(ImmutableArray<string> payloads) =>
		string.Join("\n", payloads.Select(p =>
			$"\t\tif (!model.IsDefined(typeof(global::Norse.Abstractions.Contracts.Outcome<{p}>)))\n" +
			$"\t\t\tmodel.Add(typeof(global::Norse.Abstractions.Contracts.Outcome<{p}>), applyDefaultBehaviour: false).SetSurrogate(typeof({p}));"));

	static string AddClients(ImmutableArray<string> contractTypeNames) =>
		string.Join("\n", contractTypeNames.Select(c =>
			$"\t\tglobal::Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions.AddSingleton(\n" +
			$"\t\t\tservices, global::ProtoBuf.Grpc.Client.GrpcClientFactory.CreateGrpcService<{c}>(invoker));"));
}
